// The LLM already did the heavy lifting; we just parse its JSON output.
const raw = String($json.text ?? '');

let extracted = {};
try {
  // Strip accidental markdown fences if Gemini adds them
  const clean = raw.replace(/^```(?:json)?s*/i, '').replace(/s*```$/, '').trim();
  extracted = JSON.parse(clean);
} catch (e) {
  // If JSON is malformed, surface a clear error below via parseErrors
}

// Map LLM output → workflow fields
const chatInput    = String(extracted.chatInput    ?? '').trim();
const listingId    = String(extracted.listing_id   ?? '').toLowerCase().trim();
const locality     = String(extracted.locality      ?? '').trim();
const buildingType = String(extracted.building_type ?? '').trim();
const city         = String(extracted.city          ?? '').trim();
const zone         = String(extracted.zone          ?? '').trim();
const area         = Number(extracted.area          ?? 0);
const price        = Number(extracted.price         ?? 0);

// ── SQL injection guard ─────────────────────────────────────────────
const sqlEsc = s => s.replace(/'/g, "''");

// Build WHERE using every field the LLM was able to extract,
// matching the actual DB column names from the properties table.
const conditions = [];
if (locality)     conditions.push(`LOWER(locality)      = LOWER('${sqlEsc(locality)}')`);
if (buildingType) conditions.push(`LOWER(building_type) = LOWER('${sqlEsc(buildingType)}')`);
if (city)         conditions.push(`LOWER(city)          = LOWER('${sqlEsc(city)}')`);
if (zone)         conditions.push(`LOWER(zone)          = LOWER('${sqlEsc(zone)}')`);
const whereClause = conditions.length > 0 ? conditions.join(' AND ') : '1=1';

// ── validation ──────────────────────────────────────────────────────
const parseErrors = [];
if (!extracted || Object.keys(extracted).length === 0)
  parseErrors.push('could not parse the LLM extraction response — please try rephrasing');
if (!price || price <= 0)
  parseErrors.push('price per sqft not found — please mention it (e.g. "10,000 BDT per sqft")');
if (!area  || area  <= 0)
  parseErrors.push('area not found — please mention it (e.g. "2000 sqft")');

return {
  chatInput,
  listingId,
  locality,
  buildingType,
  city,
  zone,
  localitySafe:     sqlEsc(locality),
  buildingTypeSafe: sqlEsc(buildingType),
  whereClause,
  area,
  price,
  parseErrors,
  hasParseErrors: parseErrors.length > 0,
};

const row = $json;
const avgPrice       = Number(row.avg_price       ?? 0);
const stdPrice       = Number(row.std_price       ?? 0);
const avgArea        = Number(row.avg_area        ?? 0);
const stdArea        = Number(row.std_area        ?? 0);
const sampleSize     = Number(row.sample_size     ?? 0);
const submittedPrice = Number(row.submitted_price ?? 0);
const submittedArea  = Number(row.submitted_area  ?? 0);

const reasons = [];
let flagged = false;

if (sampleSize === 0) {
  reasons.push('no comparable listings found for this locality/building type');
  flagged = true;
}

if (sampleSize > 0 && sampleSize < 5) {
  reasons.push(`low comparable sample size (${sampleSize})`);
}

let zPrice = 0;
if (sampleSize > 0) {
  if (stdPrice === 0) {
    reasons.push('price has zero variance across comparables — z-score indeterminate; manual review required');
    flagged = true;
  } else {
    zPrice = (submittedPrice - avgPrice) / stdPrice;
    if (Math.abs(zPrice) > 2) {
      reasons.push(`price z-score ${zPrice.toFixed(2)} exceeds ±2 threshold`);
      flagged = true;
    }
  }
}

let zArea = 0;
if (sampleSize > 0) {
  if (stdArea === 0) {
    reasons.push('area has zero variance across comparables — z-score indeterminate; manual review required');
    flagged = true;
  } else {
    zArea = (submittedArea - avgArea) / stdArea;
    if (Math.abs(zArea) > 2) {
      reasons.push(`area z-score ${zArea.toFixed(2)} exceeds ±2 threshold`);
      flagged = true;
    }
  }
}

const priceDeltaPct = avgPrice > 0
  ? (((submittedPrice - avgPrice) / avgPrice) * 100).toFixed(1)
  : null;
const areaDeltaPct  = avgArea  > 0
  ? (((submittedArea  - avgArea)  / avgArea)  * 100).toFixed(1)
  : null;

const llmContext = {
  listingId:       row.listing_id    || 'unknown',
  locality:        row.locality      || 'unknown',
  buildingType:    row.building_type || 'unknown',
  verdict:         flagged ? 'FLAGGED' : 'OK',
  sampleSize,
  submittedPrice,
  submittedArea,
  avgPrice:       sampleSize > 0 ? avgPrice       : null,
  avgArea:        sampleSize > 0 ? avgArea        : null,
  priceDeltaPct:  sampleSize > 0 && avgPrice > 0 ? Number(priceDeltaPct) : null,
  areaDeltaPct:   sampleSize > 0 && avgArea  > 0 ? Number(areaDeltaPct)  : null,
  reasons,
  noComparables:     sampleSize === 0,
  lowSample:         sampleSize > 0 && sampleSize < 5,
  priceZeroVariance: sampleSize > 0 && stdPrice === 0,
  areaZeroVariance:  sampleSize > 0 && stdArea  === 0,
};

const verdict = flagged ? 'FLAGGED' : 'OK';

return {
  ...row,
  verdict,
  z_price:    zPrice,
  z_area:     zArea,
  reasons,
  llmContext: JSON.stringify(llmContext),
};
